import { expect, test } from "@playwright/test";
import type { Page } from "@playwright/test";
import { addSimulated, card, login, removePrinter, simulate } from "./helpers";
import { emptyLibrary, emptyQueue } from "./library-helpers";

/**
 * A plain `.gcode` sliced "for" a Simulated Printer: `layers` layers, each a
 * square wall then `lines` infill lines of `steps` short wobbly moves, with
 * PrusaSlicer's feature comments and a support column on every layer.
 */
function gcode(layers: number, lines: number, steps: number, secs = 60): string {
  const out: string[] = [
    "; generated by Gantry's end-to-end tests",
    "; printer_model = Simulated",
    `;TIME:${secs}`,
    `; total layer number: ${layers}`,
    "G90",
    "M83",
    "G28",
  ];
  for (let layer = 0; layer < layers; layer++) {
    const z = (0.2 * (layer + 1)).toFixed(2);
    out.push(";LAYER_CHANGE", `G1 Z${z} F600`, ";TYPE:External perimeter", "G1 X10 Y10 F9000");
    for (const [x, y] of [
      [110, 10],
      [110, 110],
      [10, 110],
      [10, 10],
    ])
      out.push(`G1 X${x} Y${y} E4.0`);
    out.push(";TYPE:Support material", "G1 X120 Y60", "G1 X125 Y60 E0.5", "G1 X125 Y65 E0.5");
    out.push(";TYPE:Internal infill");
    for (let line = 0; line < lines; line++) {
      const y = 12 + (96 * line) / lines;
      out.push(`G1 X12 Y${y.toFixed(3)} F9000`);
      for (let step = 1; step <= steps; step++) {
        const x = 12 + (96 * step) / steps;
        const wobble = step % 2 === 0 ? 0.02 : -0.02;
        out.push(`G1 X${x.toFixed(3)} Y${(y + wobble).toFixed(3)} E0.0400`);
      }
    }
  }
  return out.join("\n") + "\n";
}

async function upload(page: Page, name: string, text: string): Promise<number> {
  const response = await page.request.post(`/api/print-files?name=${encodeURIComponent(name)}`, {
    headers: { "content-type": "application/octet-stream" },
    data: Buffer.from(text),
    timeout: 120_000,
  });
  expect(response.status(), await response.text()).toBe(201);
  return ((await response.json()) as { id: number }).id;
}

test("a toolpath of tens of megabytes streams in without freezing the page; the layer slider and both colour modes work", async ({
  page,
}) => {
  test.setTimeout(240_000);
  await login(page);
  await emptyQueue(page);
  await emptyLibrary(page);
  const big = gcode(240, 60, 60);
  expect(big.length).toBeGreaterThan(20 * 1024 * 1024);
  const id = await upload(page, "big-toolpath.gcode", big);

  // Watch for frozen frames: the longest gap between animation frames.
  await page.addInitScript(() => {
    const w = window as unknown as { __longest: number; __when: string };
    w.__longest = 0;
    w.__when = "";
    let last = performance.now();
    let before = "";
    const tick = (now: number) => {
      const viewer = document.querySelector<HTMLElement>(".toolpath");
      const state = `${viewer?.dataset.loadedLayers ?? "?"} layers loaded, colour by ${viewer?.dataset.mode ?? "?"}`;
      if (now - last > w.__longest) w.__when = `from ${before} to ${state}`;
      before = state;
      w.__longest = Math.max(w.__longest, now - last);
      last = now;
      requestAnimationFrame(tick);
    };
    requestAnimationFrame(tick);
  });
  await page.goto(`/library/${id}/plates/1/toolpath`);
  const viewer = page.locator(".toolpath");
  await expect(page.getByTestId("toolpath-canvas")).toBeVisible({ timeout: 120_000 });
  // From here on, only the toolpath's streaming and drawing is timed.
  await page.evaluate(() => {
    (window as unknown as { __longest: number }).__longest = 0;
  });
  await expect(viewer).toHaveAttribute("data-layers", "240", { timeout: 120_000 });
  // While it loads, the page still answers.
  await page.getByLabel("Colour by").selectOption("filament");
  await expect(viewer).toHaveAttribute("data-mode", "filament");
  await expect(viewer).toHaveAttribute("data-loaded-layers", "240", { timeout: 120_000 });
  const { longest, when } = await page.evaluate(() => {
    const w = window as unknown as { __longest: number; __when: string };
    return { longest: w.__longest, when: w.__when };
  });
  // A frozen browser would stall for seconds; drawing in small batches keeps every frame short.
  expect(longest, `the longest frame took ${Math.round(longest)} ms, with ${when}`).toBeLessThan(500);

  // The slider shows the layers up to the one chosen.
  await expect(page.getByTestId("toolpath-layer")).toHaveText("Layer 240 of 240 · 48.00 mm");
  const slider = page.getByLabel("Layer", { exact: true });
  await slider.fill("10");
  await expect(page.getByTestId("toolpath-layer")).toHaveText("Layer 10 of 240 · 2.00 mm");
  // Both colour modes, with their legends.
  await page.getByLabel("Colour by").selectOption("feature");
  await expect(viewer).toHaveAttribute("data-mode", "feature");
  const legend = page.getByRole("list", { name: "Colours" });
  await expect(legend).toContainText("Walls");
  await expect(legend).toContainText("Infill");
  await expect(legend).toContainText("Supports");
  await page.getByLabel("Colour by").selectOption("filament");
  await expect(legend).toContainText("Filament 1");

  await emptyLibrary(page);
});

test("during a live Job the toolpath highlights the layer the Simulated Printer reports, and follows it", async ({
  page,
}) => {
  await login(page);
  await emptyQueue(page);
  await emptyLibrary(page);
  const printer = await addSimulated(page, "Toolpath Sim", { model: "Simulated" });
  await page.request.put(`/api/printers/${printer}/automation`, { data: { auto_start: false } });
  const id = await upload(page, "live-toolpath.gcode", gcode(30, 4, 4, 300));
  await expect(card(page, "Toolpath Sim").getByTestId("state")).toHaveText("Idle");
  // 300 s at 20x: a layer about every half a second.
  await simulate(page, printer, { action: "set_speed", speed: 20 });
  const started = await page.request.post(`/api/printers/${printer}/start`, { data: { print_file_id: id } });
  expect(started.status(), await started.text()).toBe(201);

  await page.goto(`/printers/${printer}`);
  const viewer = page.locator(".toolpath");
  await expect(viewer).toHaveAttribute("data-loaded-layers", "30", { timeout: 30_000 });
  const live = page.getByTestId("highlighted-layer");
  await expect(live).toContainText("Toolpath Sim is printing layer");

  // The highlight follows the layer the Printer reports, as its card shows it.
  const reported = async () =>
    Number((await card(page, "Toolpath Sim").getByTestId("layer").textContent())?.split(" ")[0]);
  const highlighted = async () => Number(await viewer.getAttribute("data-highlight"));
  const first = await highlighted();
  await expect.poll(highlighted, { timeout: 20_000 }).toBeGreaterThan(first + 2);
  // At any moment the two agree (give or take the layer changing between reads).
  for (let i = 0; i < 3; i++) {
    const [h, r] = [await highlighted(), await reported()];
    expect(Math.abs(h - r), `highlighted ${h}, reported ${r}`).toBeLessThanOrEqual(1);
    await page.waitForTimeout(400);
  }
  // Following can be turned off, and the slider takes over.
  await page.getByLabel(/Follow Toolpath Sim/).uncheck();
  await expect(live).toHaveCount(0);
  await expect(page.getByLabel("Layer", { exact: true })).toBeEnabled();

  await page.request.post(`/api/printers/${printer}/commands`, { data: { command: "cancel" } });
  await removePrinter(page, printer);
  await emptyLibrary(page);
});
